var t=`0734-calulu-de-peixe`;var n=`world-0734`;var a=`ST`;var s=`central-africa`;var l=4;var o=54;var r={en:`Calulu de Peixe`,ua:`Калулу з рибою`};var d={en:`Calulu de Peixe is a São Tomé and Príncipe classic prepared with yellow onion, tomato, garlic, fish (unspecified). A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Калулу з рибою, страва кухні країни Сан-Томе і Принсіпі зі складниками: жовта цибуля, помідор, часник, риба (невизначений вид). Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,180,`g`],[`red-palm-oil`,55,`ml`],[`tomato`,330,`g`],[`garlic`,4,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 40 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 40 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:40,i:[[`fish-unspecified`,600,`g`],[`okra`,380,`g`],[`spinach`,240,`g`],[`water`,700,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`lemon-juice`,35,`ml`],[`table-salt`,null,`to_taste`]]}];var g={slug:t,id:n,country:`ST`,region:s,servings:4,minutes:54,title:r,text:d,steps:u};export{a as country,g as default,n as id,o as minutes,s as region,l as servings,t as slug,u as steps,d as text,r as title};